insert into public.training_sources(source_key,authority,title,source_type,canonical_url,publication_date,checked_on,license_kind,reuse_policy,normative_status,topics,notes,metadata)
values
('mlps-asr-2025','Ministero del Lavoro e delle Politiche Sociali','Accordo Stato-Regioni 17 aprile 2025 - formazione salute e sicurezza','normative_guidance','https://lavoro.gov.it/temi-e-priorita/salute-e-sicurezza/focus/pagine/accordo-stato-regioni-del-17042025-materia-di-formazione',date '2025-04-17',date '2026-10-15','official_public_source','quote_minimally_and_reference','primary',array['ASR 2025','dirigenti','formazione','salute e sicurezza'],'Pagina ufficiale MLPS dell’Accordo Rep. 59/CSR del 17/04/2025, pubblicato in GU n.119 del 24/05/2025.',jsonb_build_object('priority','primary_normative')),
('inail-sgsl','INAIL','Sistemi di gestione della salute e sicurezza sul lavoro - SGSL','technical_method','https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/migliorare-la-salute-e-la-sicurezza/sgsl.html',null,date '2026-10-15','institutional_terms','facts_and_original_didactic_rewrite','supporting',array['SGSL','organizzazione','processi','miglioramento','articolo 30'],'Riferimento INAIL per integrazione della salute e sicurezza nei processi aziendali e logica di sistema.',jsonb_build_object('priority','high_method'))
