with base as (
 select lu.id learning_unit_id,lu.stable_key,v.content from public.learning_units lu
 join lateral (select content from public.learning_unit_versions luv where luv.learning_unit_id=lu.id and luv.status='published' order by version_number desc limit 1) v on true
 where lu.stable_key in ('dirigente:ruolo-responsabilita-delega','dirigente:dvr-misure-risorse','dirigente:processi-mog-sgsl','dirigente:scenario-manageriale')
), enriched as (
 select learning_unit_id,stable_key,
 content || jsonb_build_object('didactic_version','dirigente-evidence-v2','quality',coalesce(content->'quality','{}'::jsonb)||jsonb_build_object('teacher_ready',true,'learner_ready',true,'decision_based',true,'managerial_output_required',true),'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-15','normative_validation','D.Lgs. 81/2008 vigente + ASR 17/04/2025','reuse_policy','reference_and_original_rewrite'),'evidence_sources',jsonb_build_array(jsonb_build_object('authority','Ministero del Lavoro e delle Politiche Sociali','title','Accordo Stato-Regioni 17 aprile 2025','url','https://lavoro.gov.it/temi-e-priorita/salute-e-sicurezza/focus/pagine/accordo-stato-regioni-del-17042025-materia-di-formazione','use','normative_validation','checked_on','2026-10-15'),jsonb_build_object('authority','Normattiva','title','D.Lgs. 81/2008 - testo vigente','url','https://www.normattiva.it/eli/id/2008/04/30/008G0104/CONSOLIDATED','use','normative_validation','checked_on','2026-10-15')) || case when stable_key in ('dirigente:processi-mog-sgsl','dirigente:scenario-manageriale') then jsonb_build_array(jsonb_build_object('authority','INAIL','title','Sistemi di gestione della salute e sicurezza sul lavoro - SGSL','url','https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/migliorare-la-salute-e-la-sicurezza/sgsl.html','use','management_system_reference','checked_on','2026-10-15'),jsonb_build_object('authority','INAIL','title','Condivido - sviluppo delle conoscenze sui near miss','url','https://www.inail.it/portale/it/inail-comunica/pubblicazioni/catalogo-generale/catalogo-generale-dettaglio.2025.04.condivido-approccio-integrato-in-reti-collaborative-sviluppo-conoscenze-near-miss.html','use','near_miss_method_reference','checked_on','2026-10-15')) else '[]'::jsonb end)
 || case stable_key
  when 'dirigente:ruolo-responsabilita-delega' then jsonb_build_object('power_responsibility_lab',jsonb_build_object('title','Responsabilità senza potere? Verifica la coerenza dell’assetto','matrix',jsonb_build_array('obiettivo/obbligo affidato','decisioni richieste','poteri effettivamente disponibili','budget/risorse','informazioni necessarie','vincoli/escalation','evidenza di esercizio del potere','riesame'),'scenarios',jsonb_build_array('fermare una lavorazione critica','autorizzare una misura urgente','modificare turni per garantire presenza/competenze','sospendere un appaltatore non coordinato','chiudere un’azione correttiva scaduta'),'task','Per ogni scenario stabilire se il dirigente dispone davvero di poteri e risorse coerenti. Se manca qualcosa, indicare quale escalation/decisione del livello superiore è necessaria.','delegation_check',jsonb_build_array('oggetto e confini chiari','competenze e requisiti del delegato','poteri organizzativi/gestionali coerenti','autonomia di spesa adeguata','accettazione quando richiesta','sistema di controllo/vigilanza residua nei limiti applicabili')),'anti_formalism_rule','Organigramma, delega o job description non bastano: il caso didattico deve verificare ciò che la persona può realmente decidere e fare nel lavoro quotidiano.')
  when 'dirigente:dvr-misure-risorse' then jsonb_build_object('measure_delivery_board',jsonb_build_object('title','Dal DVR alla misura chiusa e verificata','columns',jsonb_build_array('rischio/misura','priorità','misura definitiva','misura temporanea se necessaria','responsabile','budget/risorsa','scadenza','vincoli','evidenza di attuazione','verifica di efficacia','stato'),'scenario','Una misura tecnica definitiva è rinviata per budget; la misura temporanea non è formalizzata e dipende dalla memoria del reparto. Il dirigente deve decidere come mantenere il rischio sotto controllo e portare la soluzione definitiva a chiusura.','decision_questions',jsonb_build_array('Il rischio è accettabile fino alla scadenza prevista?','La misura temporanea è definita, comunicata e verificabile?','Chi ha potere e budget per la soluzione definitiva?','Quale condizione impone STOP o accelerazione?','Come dimostriamo che la misura finale funziona?')),'resource_rule','Una misura assegnata senza tempo, persone, budget o autorità necessaria è un impegno documentale, non ancora una misura organizzativa affidabile.')
  when 'dirigente:processi-mog-sgsl' then jsonb_build_object('process_control_lab',jsonb_build_object('title','Dove perde controllo il processo?','process_chain',jsonb_build_array('input/segnalazione','valutazione/priorità','decisione','responsabile','risorsa/scadenza','attuazione','evidenza','verifica efficacia','chiusura/riesame'),'cases',jsonb_build_array('anomalia manutentiva aperta da 45 giorni','acquisto di attrezzatura senza consultare requisiti di sicurezza','cambio turno che riduce gli addetti emergenza','near miss ripetuto senza modifica procedura','azione correttiva chiusa su carta ma non verificata sul campo'),'task','Individuare in quale passaggio il sistema ha perso controllo e progettare una barriera di processo, non soltanto un richiamo alle persone.'),'near_miss_to_system_loop',jsonb_build_array('raccogli fatti','analizza barriere/fattori','decidi azione','assegna responsabile e risorse','verifica attuazione','misura efficacia','aggiorna processo/DVR/procedura se necessario'))
  when 'dirigente:scenario-manageriale' then jsonb_build_object('managerial_control_room',jsonb_build_object('title','Control room: 30 minuti per stabilire priorità e governance','input_events',jsonb_build_array('due near miss simili','interferenza appaltatore non prevista','formazione obbligatoria rinviata','tre azioni correttive scadute','pressione produttiva a piano invariato'),'required_output',jsonb_build_array('azioni immediate/stop','priorità motivate','responsabile per ogni azione','risorse/poteri necessari','scadenza','informazioni da acquisire','stakeholder da coinvolgere','evidenza di chiusura','criterio di efficacia','data di riesame'),'constraint','Il gruppo non può risolvere tutto con fare più attenzione, mandare una mail o aggiornare il documento: ogni azione deve cambiare una condizione, un processo o una barriera verificabile.','debrief','Confrontare piani diversi sulla base di rischio residuo, fattibilità, tempi, responsabilità, risorse e capacità di verifica.'),'management_test','Una decisione è completa quando qualcuno può attuarla, dispone delle risorse, sa entro quando farlo e il dirigente ha definito come verificare che abbia funzionato.') end as new_content
 from base
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at)
select learning_unit_id,2,'draft',new_content,md5(new_content::text),null from enriched
on conflict (learning_unit_id,version_number) do update set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;

